  "alternatives": [
    {
      "option": "Inline email sending with retries",
      "reasonRejected": "The provider's 10 requests/second limit could be exceeded, leading to throttling errors, timeouts, and inconsistent delivery. Adding robust retry logic would still expose the system to rate‑limit violations and requires careful timeout tuning, increasing complexity without fully solving the rate‑limit issue."
    },
    {
      "option": "Cron job that sends emails in batches every minute",
      "reasonRejected": "While batching reduces per‑second load, a cron job still runs on a schedule and can miss bursts of email generation, leading to potential rate‑limit breaches during spikes. It also couples email processing to the cron schedule, making scaling harder. Additionally, migrating from inline calls to a cron job would require significant code changes and testing, and undoing the change would take a full day, making it less desirable than a queue solution."
    }
  ],
  "reversible": true,
